        " cvt.rn.satfinite.e2m1x2.f32 nr_n2, nr_f5, nr_f4;\n cvt.rn.satfinite.e2m1x2.f32 nr_n3, nr_f7, nr_f6;\n"
        " mov.b32 %0, {nr_n0, nr_n1, nr_n2, nr_n3};\n"
